            std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST),
            receiver.user_id(),
        );
    }
    bob.set_allowed(alice.account_id(), true).await.unwrap();
    alice.set_invisible(true).await.unwrap();
    bob.set_invisible(true).await.unwrap();
